+	natl* livello_ptr = reinterpret_cast<natl*>(p_ptr + (int_cast<natl*>(p)->cr3 ? 0 : 1));
+	
+	// Actually, let's just access p directly but check if p->cr3 is valid first
+	if (!p || !p->cr3) {
+		flog(LOG_WARN, "swap_out: processo %u non valido (cr3=%lx)", pid, p ? p->cr3 : 0);
+		return false;
+	}
+	if (p->livello == LIV_SISTEMA) {
+		flog(LOG_WARN, "swap_out: processo %u è un processo di sistema", pid);
+		c_abort_p();
+		return false;
+	}
+
+	// controllo che il processo non sia lo stesso che invoca la primitiva
+	if (p == esecuzione) {
