+		return false;
+	}
+
+	// controllo che il processo non sia già stato rimosso
+	if (p->swapped_out) {
+		return false;
+	}
+
+// copia la pila utente nel buffer
+	vaddr stack_bottom = fin_utn_p - DIM_USR_STACK;
+	if (!p->cr3) {
+		flog(LOG_WARN, "swap_out: cr3 nulla per processo %u", pid);
+		return false;
+	}
+	paddr pa_stack = trasforma(p->cr3, stack_bottom);
+	if (!pa_stack) {
+		flog(LOG_WARN, "swap_out: impossibile tradurre l'indirizzo della pila del processo %u", pid);
+		c_abort_p();
+		return false;
+	}
+	memcpy(buf, voidptr_cast(pa_stack), DIM_USR_STACK);
+
+	// rimuoviamo la parte utente/privata del processo
+	unmap(p->cr3, ini_utn_p, fin_utn_p,
+		[](vaddr, paddr p, int) { rilascia_frame(p); });
+
+	// segniamo che il processo è stato rimosso
+	p->swapped_out = true;
+
+	return true;
+}
+
+/*! @brief Parte C++ della primitiva swap_in()
+ *  @param pid		processo da ricaricare
+ *  @param buf		puntatore ad un buffer di dimensione DIM_USR_STACK
+ *  @return		false se il processo non esiste o è già caricato,
+ * 			o se l'operazione fallisce; true altrimenti
+ */
+extern "C" bool c_swap_in(natl pid, const char *buf)
+{
+	des_proc* p = proc_table[pid];
+	if (!p) {
+		flog(LOG_WARN, "swap_in: processo %u non esiste", pid);
+		return false;
+	}
+
+	// controllo che il processo non sia un processo di sistema
+	if (!p->cr3) {
+		flog(LOG_WARN, "swap_in: cr3 nulla per processo %u", pid);
+		return false;
+	}
+	if (p->livello == LIV_SISTEMA) {
+		flog(LOG_WARN, "swap_in: processo %u è un processo di sistema", pid);
+		c_abort_p();
+		return false;
+	}
+
+	// controllo che il processo sia stato rimosso
+	if (!p->swapped_out) {
+		return false;
+	}
+
+	// controlliamo che il buffer non causi problemi di Cavallo di Troia
+	if (!c_access(int_cast<vaddr>(buf), DIM_USR_STACK, BIT_RW, false)) {
+		flog(LOG_WARN, "swap_in: buffer non valido");
+		c_abort_p();
+		return false;
+	}
+
+	// creiamo la pila utente
+	if (!crea_pila(p->cr3, fin_utn_p, DIM_USR_STACK, LIV_UTENTE)) {
+		flog(LOG_WARN, "swap_in: creazione pila utente fallita per il processo %u", pid);
+		return false;
+	}
+
+	// inizializziamo la pila utente copiando dal buffer
+	vaddr stack_bottom = fin_utn_p - DIM_USR_STACK;
+	paddr pa = trasforma(p->cr3, stack_bottom);
+	if (!pa) {
+		flog(LOG_WARN, "swap_in: impossibile tradurre l'indirizzo della pila del processo %u", pid);
+		unmap(p->cr3, fin_utn_p - DIM_USR_STACK, fin_utn_p,
+			[](vaddr, paddr p, int) { rilascia_frame(p); });
+		return false;
+	}
+	memcpy(voidptr_cast(pa), buf, DIM_USR_STACK);
+
+	// segniamo che il processo è stato ricaricato
+	p->swapped_out = false;
+
+	// se il processo era stato schedulato mentre era rimosso, lo reinseriamo in coda pronti
+	if (p->scheduled) {
+		p->scheduled = false;
+		inserimento_lista(pronti, p);
+	}
+
+	return true;
+}


 /// @}
